-- Case columns: the photo flags and values of osxphotos that no test library holds, in the reference.
-- Changes: the plain photos (outside the trash, not in a burst, without a subtype, with attributes) in
-- ZUUID order, one per statement: ZHDRTYPE 3 (HDR) and 6 (panorama); ZDEPTHTYPE 1, NULL (both portraits)
-- and 0; ZVISIBILITYSTATE 0 and 2; ZSPATIALTYPE 2; ZCLOUDOWNERHASHEDPERSONID; ZMOMENTSHARE; the front
-- camera; an importing app; last, ZKINDSUBTYPE 1 (panorama), which takes the photo
-- out of the rule.
-- Expects: the reference (golden-regen.yml applies this file too) has every value, and TestGolden finds
-- no difference.

UPDATE ZASSET SET ZHDRTYPE = 3
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 0);

UPDATE ZASSET SET ZHDRTYPE = 6
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 1);

UPDATE ZASSET SET ZDEPTHTYPE = 1
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 2);

UPDATE ZASSET SET ZDEPTHTYPE = NULL
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 3);

UPDATE ZASSET SET ZDEPTHTYPE = 0
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 4);

UPDATE ZASSET SET ZVISIBILITYSTATE = 0
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 5);

UPDATE ZASSET SET ZVISIBILITYSTATE = 2
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 6);

UPDATE ZASSET SET ZSPATIALTYPE = 2
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 7);

UPDATE ZASSET SET ZCLOUDOWNERHASHEDPERSONID = 'TEST-OWNER-0001'
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 8);

UPDATE ZASSET SET ZMOMENTSHARE = (SELECT MIN(Z_PK) FROM ZSHARE)
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 9);

UPDATE ZADDITIONALASSETATTRIBUTES SET ZCAMERACAPTUREDEVICE = 1
WHERE ZASSET = (SELECT Z_PK FROM ZASSET
                WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                  AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
                ORDER BY ZUUID LIMIT 1 OFFSET 10);

UPDATE ZADDITIONALASSETATTRIBUTES SET ZIMPORTEDBYDISPLAYNAME = 'Test App', ZIMPORTEDBYBUNDLEIDENTIFIER = 'com.example.test'
WHERE ZASSET = (SELECT Z_PK FROM ZASSET
                WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                  AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
                ORDER BY ZUUID LIMIT 1 OFFSET 11);

UPDATE ZASSET SET ZKINDSUBTYPE = 1
WHERE Z_PK = (SELECT Z_PK FROM ZASSET
              WHERE ZTRASHEDSTATE = 0 AND ZKIND = 0 AND COALESCE(ZKINDSUBTYPE, 0) = 0 AND ZAVALANCHEUUID IS NULL
                AND Z_PK IN (SELECT ZASSET FROM ZADDITIONALASSETATTRIBUTES)
              ORDER BY ZUUID LIMIT 1 OFFSET 12);
